import { useState, useEffect, useRef, useMemo, type ReactNode, type FC, type MouseEvent } from 'react'
import type { SubscriptionPopupProcessData } from './types'
import * as yup from 'yup'
import type { AsyncThunk, AsyncThunkConfig } from '@reduxjs/toolkit'
import { useAppDispatch, useAppSelector } from '../../../redux/hooks'
import { fetchSubscribe } from '../../../redux/selectors/subscribe'
import type { CustomSubscribePayload, DiscountSubscribePayload, SubscribeResponse } from '../../../types/subscribe'
import { setSubscriptionCookie } from '../../../utils/cookies'
import PopupWrap, { type PopupRefProps } from '../PopupWrap'
import Image from '../../Common/Image'
import logo from '../../../assets/images/popup-logo-white.svg'
import ChevronDownIcon from '../../../assets/icons/ChevronDownIcon'

import { useDynamicSlice } from '../../../hooks/dynamic-slice'
import { useOutsideClick } from '../../../hooks/outside-click'

const models: string[] = [
    'Model 3 ‘17-20',
    'Model 3 ‘21-23',
    'Model 3 Highland',
    'Model Y ‘21-24',
    'Model Y Juniper',
    'Model S ‘21+',
    'Model X ‘21+'
]

interface SelectionPopupProps {
    background: ReactNode
    open: boolean
    popupProcessData: SubscriptionPopupProcessData
    onSuccess?: () => void
    onError?: () => void
}

type SubscriptionPayload = { email: string; model: string }

const subscribeSchema = yup.object<Record<keyof SubscriptionPayload, typeof yup>>({
    email: yup.string().email('Email not valid').required('Fill in the field'),
    model: yup.string(),
}).required()

const SelectionPopup: FC<SelectionPopupProps> = ({ background, open, popupProcessData, onSuccess = () => {}, onError = () => {} }) => {
    const wrap = useRef<PopupRefProps>(null)

    const dispatch = useAppDispatch()

    const { discountSubscribe, customSubscribe } = useDynamicSlice('subscribe', () => import('../../../redux/slices/subscribe'))

    const subscriptionMethods: Record<
        string,
        AsyncThunk<SubscribeResponse, DiscountSubscribePayload | CustomSubscribePayload, AsyncThunkConfig>
    > = useMemo(() => ({
        discount: discountSubscribe,
        custom: customSubscribe
    }), [discountSubscribe, customSubscribe])

    const popupDropdownRefs = useRef<(HTMLDivElement | null)[]>([])

    const setPopupDropdownRef = (index: number) => (el: HTMLDivElement | null) => {
        popupDropdownRefs.current[index] = el
    }
    
    useOutsideClick(popupDropdownRefs, () => {
        if (modelsDropdownOpen) setModelsDropdownOpen(false)
    })

    const [modelsDropdownOpen, setModelsDropdownOpen] = useState<boolean>(false)
    const [data, setData] = useState<SubscriptionPayload>({ email: '', model: '' })
    const [errors, setErrors] = useState<Record<keyof SubscriptionPayload, string | null>>({ email: null, model: null })

    const { customSubscribed, discountSubscribed, error: apiError } = useAppSelector(fetchSubscribe)

    useEffect(() => {
        if (popupProcessData) {
            setData(prev => ({ ...prev, ...popupProcessData }))
        }
    }, [popupProcessData])

    const handleChange = (param: keyof SubscriptionPayload, value: string) => {
        setErrors(prev => ({ ...prev, [param]: null }))
        setData(prev => ({ ...prev, [param]: value }))
    }

    const handleModelSelect = (e: MouseEvent<HTMLDivElement>, model: string | null | undefined = null) => {
        e.stopPropagation()
        handleChange('model', model || '')
        setModelsDropdownOpen(false)
    }
    
    const validateForm = async (formData: SubscriptionPayload) => {
        try {
            await subscribeSchema.validate(formData, { abortEarly: false })
            return true
        } catch (e: any) {
            setErrors({
                ...errors,
                ...e.inner.reduce((acc: any, error: any) => ({ ...acc, [error.params.path]: error.message }), {})
            })
            return false
        }
    }

    const subscribe = async (withModel = true) => {
        const formValid = await validateForm(data)
        if (formValid) {
            const { email, model } = data
            const mode = popupProcessData?.mode || null
            if (mode) {
                dispatch(subscriptionMethods[mode as string]({
                    name: email,
                    email,
                    tesla_models: model && withModel ? [model] : []
                }))
            }
        }
    }

    const handleSubscribe = () => {
        subscribe(true)
    }

    const handleCancel = () => {
        subscribe(false)
    }

    useEffect(() => {
        const mode = popupProcessData?.mode || null
        if (mode) {
            const subscribed = {
                discount: discountSubscribed,
                custom: customSubscribed,
            }[mode as string]
            if (subscribed) {
                setSubscriptionCookie(`${mode}_subscription`, 1)
                wrap?.current?.close(() => onSuccess())
            }
        }
    }, [popupProcessData, discountSubscribed, customSubscribed])
        
    useEffect(() => {
        if (apiError) {
            if (apiError === 'email_exists') {
                wrap?.current?.close(() => onError())
            } else {
                setErrors(prev => ({ ...prev, model: 'An error occurred, try again' }))
            }
        }
    }, [apiError])

    return (
        <PopupWrap
            ref={wrap}
            id="selection-popup"
            className="selection-popup"
            backgroundType="node"
            background={background}
            open={open}
            onClose={handleCancel}
        >
            <div className="subscription-popup-head">
                <Image className="subscription-popup-logo" src={logo} alt="SCREENMATE" />
                <div className="subscription-popup-info">
                    <div className="subscription-popup-title">
                        We’d love to make <br className="mobile" />our <br className="desktop" />emails more <br className="mobile" />useful for you.
                    </div>
                    <div className="subscription-popup-subtitle">
                        Tell us your Tesla model so we can send <br />you the updates that matter most.
                    </div>
                </div>
            </div>
            <div className="subscription-popup-form">
                <div className="subscription-popup-fields">
                    <div className={`subscription-popup-field ${errors.model ? 'subscription-popup-field-error' : ''}`}>
                        <label>Tesla model:</label>
                        <div
                            className="subscription-popup-field-select"
                            onClick={(e) => {
                                e.stopPropagation()
                                setModelsDropdownOpen(true)
                            }}
                        >
                            <span className="subscription-popup-field-select-value">
                                {data.model || 'Select your Tesla model and year'}
                            </span>
                            <div className="subscription-popup-field-select-arrow">
                                <ChevronDownIcon />
                            </div>
                            {modelsDropdownOpen && (
                                <div ref={setPopupDropdownRef(0)} className="subscription-popup-field-select-dropdown">
                                    <div
                                        className="subscription-popup-field-select-dropdown-item"
                                        onClick={handleModelSelect}
                                    >
                                        <span>Select your Tesla model and year</span>
                                        <div className="subscription-popup-field-select-arrow">
                                            <ChevronDownIcon color='#B9B9B9' />
                                        </div>
                                    </div>
                                    {models.map((model, index) => (
                                        <div
                                            key={index}
                                            className="subscription-popup-field-select-dropdown-item"
                                            onClick={(e) => handleModelSelect(e, model)}
                                        >
                                            <span>{model}</span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                        {errors.model && <span className="subscription-popup-field-error-message">{errors.model}</span>}
                    </div>
                </div>
                <div className="subscription-popup-buttons">
                    <button className="subscription-popup-submit" onClick={handleSubscribe}>
                        Select
                    </button>
                </div>
            </div>
        </PopupWrap>
    )
}

export default SelectionPopup
